}

function calc(a, op, b) {
  switch (op) {
    case "+": return a + b;
    case "-": return a - b;
    case "*": return a * b;
    case "/": return b === 0 ? "∞ (divide by zero)" : a / b;
    default: return "unknown op";
  }
}
const jobs = [[12, "+", 5], [12, "-", 5], [12, "*", 5], [12, "/", 5], [12, "/", 0]];
for (const [a, op, b] of jobs) {
  console.log(`${a} ${op} ${b} =`, calc(a, op, b));
}

function scorePassword(pw) {
  let score = 0;
  const tips = [];
  if (pw.length >= 8) score += 2; else tips.push("use 8+ chars");
  if (pw.length >= 12) score += 1;
  if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) score += 2; else tips.push("mix upper/lower");
  if (/\d/.test(pw)) score += 2; else tips.push("add a digit");
  if (/[^A-Za-z0-9]/.test(pw)) score += 2; else tips.push("add a symbol");
  const label = score >= 8 ? "strong" : score >= 5 ? "okay" : "weak";
  return { score, label, tips };
}
for (const pw of ["abc", "CodeItAll1", "C0de!tAll#2026"]) {
  const r = scorePassword(pw);
  console.log(`"${pw}" → ${r.label} (${r.score})`, r.tips.length ? r.tips : "nice!");
}

