function fibLoop(n) {
  if (n < 2) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) [a, b] = [b, a + b];
  return b;
}
const memo = { 0: 0, 1: 1 };
function fibMemo(n) {
  if (memo[n] !== undefined) return memo[n];
  return (memo[n] = fibMemo(n - 1) + fibMemo(n - 2));
}
const n = 15;
console.log("loop:", Array.from({ length: n }, (_, i) => fibLoop(i)).join(" "));
