class BankAccount {
  #balance;
  constructor(owner, opening = 0) {
    this.owner = owner;
    this.#balance = opening;
    this.ledger = [];
  }
  deposit(amount) {
    this.#balance += amount;
    this.ledger.push(`+${amount}`);
  }
  withdraw(amount) {
    if (amount > this.#balance) {
      this.ledger.push(`denied ${amount}`);
      return false;
    }
    this.#balance -= amount;
    this.ledger.push(`-${amount}`);
    return true;
  }
  get balance() { return this.#balance; }
}
