    const data = await res.json();
    const joke = Array.isArray(data) ? data[0] : data;
    return { setup: joke.setup, punchline: joke.punchline, source: "api" };
  } catch (err) {
    console.log("Network fallback:", String(err.message || err));
    return { ...fallback, source: "offline" };
