const notes = [261.63, 329.63, 392.0, 523.25]; // C E G C
async function play() {
  const AC = typeof AudioContext !== "undefined" ? AudioContext : null;
  if (!AC) {
    console.log("No AudioContext — frequencies:", notes.join(", "));
    return;
  }
  const ctx = new AC();
  let t = ctx.currentTime;
  for (const f of notes) {
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.frequency.value = f;
    o.type = "sine";
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.2, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
    o.connect(g); g.connect(ctx.destination);
    o.start(t); o.stop(t + 0.2);
    t += 0.22;
  }
  console.log("Beeps scheduled — listen if your browser allows audio.");
  await new Promise((r) => setTimeout(r, 1000));
  await ctx.close();
}
play();
